#!/usr/bin/env bash
# Tier 1: the FREESTANDING native library (scripts/build_native.sh: the generated C of LeanSse, abi/vbm_sse.c and runtime/rt.c, -ffreestanding -nostdlib, no libc) against the Lean reference.
#   1. Builds it; `nm -u` of the object and the shared library is EMPTY and the only global symbols defined are vbm_sse_new, vbm_sse_feed and vbm_sse_free.
#   2. The shared vectors (vbm-sse-vectors-1, generated by the Lean REFERENCE) go through tests/abi_test.c linked against ONLY this library: every row on every cut (whole, byte by byte, each two-way
#      split), the argument checks, and the leak hook (the runtime's live bytes are flat over 2000 streams).
#   3. tests/lean_layout.c: abi/lean_mini.h (the freestanding stand-in for lean.h, used by the shim here and by the scorecard's freestanding compile) agrees with lean.h.
# NEGATIVE self-tests, in the same run: a build that links malloc (the runtime's malloc renamed away, so the object needs libc's) fails the nm check naming it; so does a file that calls printf; corrupted
# expected events and reconnection time each fail the test; a mutated lean_mini.h tag and header layout fail the layout test; mutants of the runtime (ByteArray.push, Array.push, ByteArray.extract,
# ByteArray equality, free) and of the shim (a dropped reference, the report's pointer, the length limit) each fail the test.
# Run: mise exec -- scripts/test_native.sh
set -euo pipefail
cd "$(dirname "$0")/.."
. scripts/lib-ran.sh   # ran_case / ran_done / must_fail: the self-tests count what they executed and a refused tool is a failure (docs/decisions/0002-ran-evidence.md)
tmp=$(mktemp -d); trap 'rm -rf "$tmp"' EXIT
. scripts/lib-no-crash-record.sh; nocrash_build   # probes and mutants that are meant to crash run under `quiet` (no core, no systemd-coredump record); ulimit -c does not stop the record
sysinc_flags() { printf '%s\n' -isystem "$1"; [ ! -d "$1/$(uname -m)-linux-gnu" ] || printf '%s\n' -isystem "$1/$(uname -m)-linux-gnu"; }
mapfile -t SYSFLAGS < <(sysinc_flags "${VBM_SSE_SYSINCLUDE:-/usr/include}")
# Independent negative self-tests run concurrently: bgj CMD..., joinj (docs/decisions/0004-tier1-speed.md).
jpids=(); bgj() { "$@" & jpids+=($!); }; joinj() { local p; for p in "${jpids[@]}"; do wait "$p" || exit 1; done; jpids=(); }
changed() { cmp -s "$1" "$2" && { echo "test_native: self-test: the corruption of $3 changed nothing" >&2; exit 1; } || true; }
lake build vbm-sse-vectors LeanSse:static >/dev/null
# 1. the build and its symbols
keepsyms="vbm_sse_rt_live"
VBM_KEEP="$keepsyms" scripts/build_native.sh "$tmp/lib" > "$tmp/build.txt"; sed 's/^/test_native: /' "$tmp/build.txt"
scripts/build_native.sh "$tmp/pub" > /dev/null   # the shipped build: no hook symbol
for f in "$tmp/pub/vbm_sse.o"; do
  [ -z "$(nm -u "$f")" ] || { echo "test_native: $f has undefined symbols" >&2; exit 1; }
  [ "$(nm -g --defined-only "$f" | sed 's/^[0-9a-f]* . //' | sort | tr '\n' ' ')" = "vbm_sse_feed vbm_sse_free vbm_sse_new " ] || { echo "test_native: $f exports more than the ABI" >&2; nm -g --defined-only "$f" >&2; exit 1; }
done
[ -z "$(nm -D -u "$tmp/pub/libvbm_sse.so")" ] || { echo "test_native: libvbm_sse.so has undefined symbols" >&2; exit 1; }
[ "$(nm -D --defined-only "$tmp/pub/libvbm_sse.so" | sed 's/^[0-9a-f]* . //' | sort | tr '\n' ' ')" = "vbm_sse_feed vbm_sse_free vbm_sse_new " ] || { echo "test_native: libvbm_sse.so exports more than the ABI" >&2; exit 1; }
echo "test_native: nm -u is empty for the object and the shared library; the only exports are vbm_sse_new, vbm_sse_feed and vbm_sse_free"
# negative: the nm check can fail (a libc function the library needs)
sed 's/^void \*malloc(size_t n)/void *vbm_not_malloc(size_t n)/' runtime/rt.c > "$tmp/nomalloc.c"; changed runtime/rt.c "$tmp/nomalloc.c" "the malloc rename"
bgj must_fail "a build that links malloc" env VBM_RT_C="$tmp/nomalloc.c" scripts/build_native.sh "$tmp/neg1" --no-so
printf 'int printf(const char *, ...);\nint vbm_x(void) { return printf("x"); }\n' > "$tmp/pf.c"
bgj must_fail "a file that calls printf" env VBM_EXTRA_C="$tmp/pf.c" VBM_KEEP=vbm_x scripts/build_native.sh "$tmp/neg2" --no-so
# 2. the vectors against this library only
lake exe vbm-sse-vectors --n 3 --out "$tmp/v.jsonl" >/dev/null 2>&1
v="$tmp/v.jsonl"
build_test() { leanc "${SYSFLAGS[@]}" -Wall -Wextra -Werror -I include -o "$2" tests/abi_test.c "$1/libvbm_sse.a"; }   # build_test LIBDIR OUT
build_test "$tmp/lib" "$tmp/abi_test"
quiet "$tmp/abi_test" "$v" | sed 's/^/test_native: /'; ran_case   # the positive run: the control of the negative self-tests
sed '0,/"events":\[{"type":"6d657373616765"/s//"events":[{"type":"6d657373616766"/' "$v" > "$tmp/c1.jsonl"; changed "$v" "$tmp/c1.jsonl" "an event type"
bgj must_fail "a corrupted expected event" quiet "$tmp/abi_test" "$tmp/c1.jsonl"
sed '0,/"retry":18446744073709551615/s//"retry":18446744073709551614/' "$v" > "$tmp/c2.jsonl"; changed "$v" "$tmp/c2.jsonl" "the saturated reconnection time"
bgj must_fail "a corrupted expected reconnection time" quiet "$tmp/abi_test" "$tmp/c2.jsonl"
# 3. lean_mini.h against lean.h
layout() { leanc "${SYSFLAGS[@]}" -Wall -Wextra -Werror -I include -o "$1/layout" "$1/tests/lean_layout.c" && quiet "$1/layout"; }   # layout DIR: DIR has tests/ and abi/
mkdir -p "$tmp/L/tests" "$tmp/L/abi"; cp tests/lean_layout.c "$tmp/L/tests/"; cp abi/lean_mini.h "$tmp/L/abi/"
layout "$tmp/L" | sed 's/^/test_native: /'
mkdir -p "$tmp/M/tests" "$tmp/M/abi"; cp tests/lean_layout.c "$tmp/M/tests/"; sed 's/#define LeanScalarArray 248/#define LeanScalarArray 247/' abi/lean_mini.h > "$tmp/M/abi/lean_mini.h"; changed abi/lean_mini.h "$tmp/M/abi/lean_mini.h" "lean_mini.h"
bgj must_fail "a mutated lean_mini.h tag" layout "$tmp/M"
mkdir -p "$tmp/N/tests" "$tmp/N/abi"; cp tests/lean_layout.c "$tmp/N/tests/"; sed 's/unsigned m_other:8; unsigned m_tag:8;/unsigned m_tag:8; unsigned m_other:8;/' abi/lean_mini.h > "$tmp/N/abi/lean_mini.h"; changed abi/lean_mini.h "$tmp/N/abi/lean_mini.h" "lean_mini.h"
bgj must_fail "a mutated lean_mini.h header layout" layout "$tmp/N"
mkdir -p "$tmp/O/tests" "$tmp/O/abi"; cp tests/lean_layout.c "$tmp/O/tests/"; sed 's/if (o->m_rc > 0) o->m_rc++;/o->m_rc++;/' abi/lean_mini.h > "$tmp/O/abi/lean_mini.h"; changed abi/lean_mini.h "$tmp/O/abi/lean_mini.h" "lean_mini.h"
bgj must_fail "a mutated lean_mini.h count increment" layout "$tmp/O"
# mutants of the runtime and of the shim: the library built from each must fail the vector test
mutant() {  # mutant NAME RT|ABI FROM TO: replace FROM by TO (it must occur) in runtime/rt.c or abi/vbm_sse.c; the test built on the mutated library has to fail
  local n=$1 file=runtime/rt.c var=VBM_RT_C d="$tmp/mut_$1"; [ "$2" = ABI ] && { file=abi/vbm_sse.c; var=VBM_ABI_C; }
  mkdir -p "$d/abi" "$d/include" "$d/runtime"; cp abi/lean_mini.h "$d/abi/"; cp include/vbm_sse.h "$d/include/"   # the mutated shim finds its headers as the real one does
  python3 -c 'import sys; s = open(sys.argv[1]).read(); assert sys.argv[2] in s, "mutant " + sys.argv[4] + ": the text to mutate is not in " + sys.argv[1]; open(sys.argv[5], "w").write(s.replace(sys.argv[2], sys.argv[3], 1))' "$file" "$3" "$4" "$n" "$d/$file"
  changed "$file" "$d/$file" "mutant $n"
  env "$var=$d/$file" VBM_KEEP="$keepsyms" scripts/build_native.sh "$tmp/m_$n" --no-so >/dev/null
  build_test "$tmp/m_$n" "$tmp/m_$n/t"
  must_fail "mutant $n" quiet "$tmp/m_$n/t" "$v"
}
bgj mutant bytepush RT 'lean_sarray_cptr(r)[sz] = b;' 'lean_sarray_cptr(r)[sz] = b + 1;'
bgj mutant arraypush RT 'lean_array_cptr(r)[sz] = v;' 'lean_array_cptr(r)[sz] = lean_array_cptr(r)[sz ? sz - 1 : 0]; if (!sz) lean_array_cptr(r)[0] = v;'
bgj mutant extract RT 'if (len) memcpy(lean_sarray_cptr(r), lean_sarray_cptr(a) + bi, len);' 'if (len) memcpy(lean_sarray_cptr(r), lean_sarray_cptr(a) + bi + 1, len - 1);'
bgj mutant sarrayeq RT 'return memcmp(lean_sarray_cptr(a), lean_sarray_cptr(b), n) == 0;' '(void)n; return 1;'
bgj mutant nofree RT 'live_ -= c; *(void **)p = *list; *list = p;' '*(void **)p = *list; *list = p;'
bgj mutant shim_noinc ABI '  lean_inc_ref(r->state);' '  '
bgj mutant shim_report ABI 'rep->nbytes = lean_sarray_size(r->report);' 'rep->nbytes = lean_sarray_size(r->report) - 1;'
bgj mutant shim_limit ABI 'len >= (size_t)LEAN_MAX_SMALL_NAT' 'len > 3'
bgj mutant shim_leak ABI '  if (r->report) lean_dec_ref(r->report);
  lean_dec_ref(r->state);' '  lean_dec_ref(r->state);'
joinj
ran_done test_native
echo "test_native: ok (negative self-tests: a build linking malloc and one calling printf fail the nm check; a corrupted expected event and reconnection time, lean_mini.h tag, layout and count increment, and runtime mutants bytepush, arraypush, extract, sarrayeq, nofree and shim mutants noinc, report, limit, leak each fail)"
